374	/**
375	 * Render a product detail view that includes name, image gallery, price,
376	 * variant selections, action buttons
377	 */
378	
379	const ProductView = forwardRef(
380	  (
381	    {
382	      product,
383	      category,
384	      showFullLink = false,
385	      // SFCC-731 review finding (CodeRabbit, 2026-09-02): ZimmProductGallery has no
386	      // size-variant concept, so this was briefly a no-op — a real regression for the
387	      // unmodified base callers that pass imageSize="sm" (product-view-modal's quick-view and
388	      // bundle paths, bonus-product-view-modal), whose compact-modal gallery would otherwise
389	      // have silently switched to the full PDP gallery. Fixed by branching on it below: 'sm'
390	      // keeps the base ImageGallery exactly as before, ZimmProductGallery only renders for the
391	      // PDP's own 'md' (default) path.
392	      imageSize = 'md',
393	      isWishlistLoading = false,
394	      addToCart,
395	      updateCart,
396	      addToWishlist,
397	      removeFromWishlist,
398	      wishlistedProductIds = [],
399	      isWishlistMutating = false,
400	      isProductLoading,
401	      isProductPartOfSet = false,
402	      isProductPartOfBundle = false,
403	      childOfBundleQuantity = 0,
404	      childProductOrderability,
405	      setChildProductOrderability,
406	      isBasketLoading = false,
407	      onVariantSelected = () => {},
408	      validateOrderability = (variant, product, quantity, stockLevel) => {
409	        if (isProductLoading) return false;
410	
411	        // If product has variations, a variant must be selected
412	        if (product?.variationAttributes?.length > 0 && !variant) {
413	          return false;
414	        }
415	
416	        // Check if product (either variant or standard) is orderable and if quantity is valid
417	        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
418	      },
419	      showImageGallery = true,
420	      setSelectedBundleQuantity = () => {},
421	      selectedBundleParentQuantity = 1,
422	      pickupInStore = false,
423	      setPickupInStore = () => {},
424	      onOpenStoreLocator = () => {},
425	      showDeliveryOptions = true,
426	      customButtons = [],
427	      maxOrderQuantity = null,
428	      basketProductItems = [],
429	      imageGalleryFooter = null,
430	      controlledVariationValues = null,
431	      onVariationChange = null,
432	      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
433	      renderVariationAttribute,
434	      footerLinks = null,
435	      showQuantityPicker = true,
436	      showStockMessage = true,
437	      showActionButtons = true,
438	      onFindYourSizeClick,
439	      onSizeGuideClick,
440	    }: ProductViewProps,
441	    ref: ProductViewRef,
442	  ) => {
443	    const { currency: activeCurrency } = useCurrency();
444	    const showToast = useToast();
445	    const intl = useIntl();
446	    const buildHref = useSafeHref();
447	    const location = useLocation();
448	    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
449	    const {
450	      isOpen: isAddToCartModalOpen,
451	      onOpen: onAddToCartModalOpen,
452	      onClose: onAddToCartModalClose,
453	    } = useAddToCartModalContext();
454	
455	    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
456	    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');
457	
458	    const theme = useTheme();
459	    const { confirmingBasket } = useSFPayments();
