/*
 * Copy-first port of
 * node_modules/@salesforce/retail-react-app/app/components/product-view/index.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
 *
 * Apart from the one added prop described in the next paragraph, the differences from the base
 * file are the TypeScript annotations below, house formatting, and a small number of
 * optional-chaining guards that strictNullChecks requires — each flagged in place with a
 * `Deviation from the base file` comment.
 *
 * Per the SFCC bridge pattern in .claude/rules/overrideStyling.md, the default export stays a
 * faithful port with the same `forwardRef` behaviour. It carries exactly one additive optional
 * prop over the base file's surface — `renderHeader`, documented on `ProductViewProps` below.
 * It is behaviour-preserving when omitted (its default renders the same private
 * `ProductViewHeader` the base file renders inline), and `renderHeader` has zero occurrences in
 * the base package, so none of the four base modules that import ProductView — product-view-modal
 * (index and bundle), bonus-product-view-modal, and pages/product-detail — passes it or is
 * affected by it. (The runtime `propTypes` blocks are replaced by the TypeScript prop types; see
 * the note at the foot of the file.)
 */

import React, { forwardRef, useEffect, useMemo, useRef, useState, useCallback } from 'react';
import { ZimmSizeSelector, type ZimmSizeSelectorHandle } from '../ui-kits/molecules/zimmSizeSelector';
import { ZimmButton } from '../ui-kits/atoms/zimmButton';
import { ZimmWishlistBadge } from '../ui-kits/atoms/zimmWishlistBadge';
import { useLocation } from 'react-router-dom';
import { useIntl, FormattedMessage } from 'react-intl';

import {
  Flex,
  Heading,
  Button,
  Skeleton,
  AspectRatio,
  Box,
  Text,
  VStack,
  Fade,
  Stack,
  Radio,
  RadioGroup,
  useTheme,
} from '@salesforce/retail-react-app/app/components/shared/ui';

import { useCurrency, useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
import { useAddToCartModalContext } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
import { useSFPayments, useExpressCheckoutEnabled } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';

// project components
// Base compact gallery — still used for imageSize="sm" callers (product-view-modal's
// quick-view and bundle paths, bonus-product-view-modal). See the imageSize destructuring
// below for why this stays alongside ZimmProductGallery rather than being replaced entirely.
import ImageGallery from '@salesforce/retail-react-app/app/components/image-gallery';
import { Skeleton as ImageGallerySkeleton } from '@salesforce/retail-react-app/app/components/image-gallery';
// SFCC-731 — Zimmermann gallery, PDP path only (imageSize="md", the default). Relative, not
// the SFCC base `image-gallery` path: this component isn't shadowing that base module (see
// zimmProductGallery's own doc comment for why), so there is nothing for the overrides
// resolver to redirect here.
import { ZimmProductGallery } from '../ui-kits/organisms/zimmProductGallery';
import { ZimmGalleryOverlay } from '../ui-kits/organisms/zimmGalleryOverlay';
import { GALLERY_ITEM_ASPECT_RATIO } from '../ui-kits/atoms/zimmMediaTile/zimmMediaTile.css';
import { mapImageGroupsToGalleryMedia } from './mapImageGroupsToGalleryMedia';
// SFCC-708 — related-colour swatches, same helper product-detail/index.tsx uses to build its
// own combined "Colour:" group. Reused here so the overlay shows the identical offered-colour
// set, not a narrower natural-variants-only one.
import { buildRelatedSwatches, type RelatedSwatch } from '../../pages/product-detail/productInfo';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import { useSafeHref } from 'app/hooks/useSafeHref';

import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
import Link from '@salesforce/retail-react-app/app/components/link';
import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive';
import QuantityPicker from '@salesforce/retail-react-app/app/components/quantity-picker';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
import Swatch from '@salesforce/retail-react-app/app/components/swatch-group/swatch';
import SwatchGroup from '@salesforce/retail-react-app/app/components/swatch-group';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
import SFPaymentsExpressButtons from '@salesforce/retail-react-app/app/components/sf-payments-express-buttons';
import { EXPRESS_BUY_NOW } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
import { useCleanupTemporaryBaskets } from '@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets';
import { ZimmWishlistAuthDrawer } from '../ui-kits/organisms/zimmWishlistAuthDrawer';

// Constants
const DELIVERY_OPTIONS = {
  DELIVERY: 'delivery',
  PICKUP: 'pickup',
};

const ADD_TO_BAG_MESSAGE = {
  defaultMessage: 'Add to Bag',
  id: 'product_view.button.add_to_bag',
} as const;

const MAX_ORDER_QTY_MESSAGE = {
  defaultMessage: 'Maximum purchase quantity reached for this size',
  id: 'product_view.message.max_order_quantity_reached',
} as const;

const MAX_ORDER_QTY_NO_SIZE_MESSAGE = {
  defaultMessage: 'Maximum purchase quantity reached',
  id: 'product_view.message.max_order_quantity_reached_no_size',
} as const;

const COLOUR_REQUIRED_MESSAGE = {
  defaultMessage: 'Please select a colour',
  id: 'product_view.message.colour_required',
} as const;

// SFCC-434 — accessible names for the header wishlist badge. Distinct message namespace
// (`.assistive_msg.`) from the existing CTA-column wishlist button's visible label messages
// above (`product_view.button.add_to_wishlist` etc.) — this badge has no visible text.
const ADD_TO_WISHLIST_ARIA_LABEL = {
  defaultMessage: 'Add to Wishlist',
  id: 'product_view.button.assistive_msg.add_to_wishlist',
} as const;

const REMOVE_FROM_WISHLIST_ARIA_LABEL = {
  defaultMessage: 'Remove from Wishlist',
  id: 'product_view.button.assistive_msg.remove_from_wishlist',
} as const;

/*
 * These are a deliberate temporary gap, NOT evidence that no type exists — do not read them
 * that way. `@salesforce/retail-react-app` ships no TypeScript types (see
 * overrides/app/types/vendor.d.ts), but the shapes underneath are `commerce-sdk-isomorphic`'s
 * and it does export them: `ShopperProductsTypes.Product` / `.Variant` / `.Category`, and
 * `.Image` for `image` below. AGENTS.md's Type Definitions rule says to import those directly.
 *
 * Substituting them is a follow-up rather than part of this PR only because it also removes
 * three `no-explicit-any` warnings, moving a lint count this branch holds as an invariant
 * across every commit.
 */
type SfccProduct = any;
type SfccVariant = any;
type SfccCategory = any;
type SfccPriceData = any;

/** One selectable value of a variation attribute, as the base hooks shape it. */
type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };

/** A variation attribute (colour, size, ...) with its selectable values. */
type SfccVariationAttribute = {
  id: string;
  name?: string;
  selectedValue?: SfccVariationValue;
  values: SfccVariationValue[];
};

/** SFCC variation attribute ID for the colour attribute. */
export const SFCC_COLOUR_ATTRIBUTE_ID = 'color';

/** SFCC variation attribute ID for the size attribute. */
export const SFCC_SIZE_ATTRIBUTE_ID = 'size';

/** The per-child orderability record ProductView writes back to its parent. */
export type ChildProductOrderability = {
  showInventoryMessage?: boolean;
  unfulfillable?: boolean;
  isOutOfStock?: boolean;
  stockLevel?: number;
  productName?: string;
};

export type ProductViewHeaderProps = {
  name?: string;
  currency?: string;
  priceData?: SfccPriceData;
  category?: SfccCategory[];
  product?: SfccProduct;
  isProductPartOfBundle?: boolean;
  /**
   * The wishlist toggle badge (SFCC-434), built by `ProductView` itself since it needs
   * internal state (`variant`, `hasSizeAttribute`, `sizeSelectorRef`) the caller does not have.
   * `undefined` for any caller that does not wire wishlist props at all. Threaded into the
   * default `ProductViewHeader` fallback too, so every caller (PDP, cart, quick-view,
   * bonus-product) gets it uniformly — there is no separate CTA-column wishlist button anymore.
   */
  wishlistButton?: React.ReactNode;
};

/*
 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
 * from the default implementation the base file supplies.
 */
type ProductViewProps = {
  product?: SfccProduct;
  category?: SfccCategory[];
  showFullLink?: boolean;
  imageSize?: 'sm' | 'md';
  isWishlistLoading?: boolean;
  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
  /**
   * Removes the current variant from the wishlist (SFCC-434, AC4) — the toggle-off half of
   * `addToWishlist`. Distinct from `updateWishlist` above, which base SFCC uses for a
   * different (already-in-basket quantity update) semantic this codebase never wires up.
   */
  removeFromWishlist?: ((product: SfccProduct, variant: SfccVariant) => unknown) | null;
  /**
   * List-item productIds currently in the customer's wishlist (SFCC-434). A plain array, not
   * a derived `isInWishlist` boolean: the currently selected size/variant lives inside this
   * component (`effectiveSizeValue`/`localSizeValue` below), not in the container, so only
   * `ProductView` itself can compute the variant-scoped result reactively — same reasoning as
   * `basketProductItems` further down for `isMaxOrderQtyReached`.
   */
  wishlistedProductIds?: ReadonlyArray<string>;
  /**
   * True while the wishlist add/remove mutation itself is in flight (SFCC-434) — distinct from
   * `isWishlistLoading` above, which reflects the wishlist *query's* loading state, not the
   * mutation's. Guards the new header badge against a double-fire mid-mutation; the existing
   * CTA-column wishlist button's own disabled check is untouched.
   */
  isWishlistMutating?: boolean;
  isProductLoading?: boolean;
  isProductPartOfSet?: boolean;
  isProductPartOfBundle?: boolean;
  childOfBundleQuantity?: number;
  childProductOrderability?: Record<string, ChildProductOrderability>;
  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
  isBasketLoading?: boolean;
  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
  validateOrderability?: (
    variant: SfccVariant,
    product: SfccProduct,
    quantity: number,
    stockLevel: number,
  ) => boolean | undefined;
  showImageGallery?: boolean;
  setSelectedBundleQuantity?: (quantity: number) => void;
  selectedBundleParentQuantity?: number;
  pickupInStore?: boolean;
  setPickupInStore?: (checked: boolean) => void;
  onOpenStoreLocator?: () => void;
  showDeliveryOptions?: boolean;
  customButtons?: React.ReactElement[];
  promotionId?: string;
  maxOrderQuantity?: number | null;
  /**
   * Basket line items from the current session, used to enforce `maxOrderQuantity`
   * per size variant (SFCC-196). Passed in from the PDP page; components under
   * `overrides/app/components/` must not call data-fetching hooks directly.
   */
  basketProductItems?: ReadonlyArray<{ productId?: string; quantity?: number }>;
  imageGalleryFooter?: React.ReactNode;
  alignItems?: string;
  controlledVariationValues?: Record<string, string> | null;
  onVariationChange?: ((attributeId: string, value: string) => void) | null;
  /**
   * The one Zimmermann addition to this component's prop surface. Replaces the header block
   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
   * them. Defaults to rendering that same private header, so every existing caller — cart,
   * wishlist, bonus-product — is byte-identical unless it opts in.
   *
   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
   * twice with the same arguments. Keep it pure.
   */
  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
  /**
   * Render slot for overriding how a single variation attribute is displayed. When provided,
   * the returned node replaces the base SwatchGroup for that attribute. Return `undefined` (or
   * omit the prop) to fall through to `renderDefaultVariationAttribute` — the base SwatchGroup
   * rendering. The PDP uses this to inject `ZimmColourSwatchGroup` for the colour attribute;
   * the quick-view modal omits it and keeps the base SwatchGroup for all attributes.
   */
  renderVariationAttribute?: (attr: SfccVariationAttribute) => React.ReactNode;
  /**
   * The second Zimmermann addition to this component's prop surface (SFCC-736/195). Renders
   * after the CTAs (`renderActionButtons()`), inside the same column — Figma's "Find in
   * Boutique" link and the Details & Care / Size Guide / Shipping & Returns / Assistance
   * drawer-trigger rows. A plain node, like the existing `imageGalleryFooter` slot, not a
   * render-prop like `renderHeader`: this content needs none of ProductView's own render-time
   * data, it is driven entirely by state the caller (`product-detail/index.tsx`) already owns.
   * `null` by default, so every existing caller (cart, wishlist, bonus-product) is unaffected.
   */
  footerLinks?: React.ReactNode;
  /**
   * Set to `false` to hide the quantity picker. Defaults to `true` so every existing caller
   * (wishlist, cart, bonus-product) is unaffected. The PDP passes `false` because quantity
   * selection is not part of the Zimmermann PDP design.
   */
  showQuantityPicker?: boolean;
  /**
   * Set to `false` to suppress the SFCC-native inventory/stock message (e.g. "Out of stock")
   * that appears below Add to Bag. Defaults to `true`. The PDP passes `false` because OOS state
   * is communicated through the size selector dropdown items and the aria-disabled button state.
   */
  showStockMessage?: boolean;
  /**
   * Set to `false` to hide the desktop action-buttons column and the sticky mobile CTA bar.
   * Defaults to `true`. The PDP passes `false` because Add to Bag is rendered inline with the
   * size selector and Add to Wishlist lives in the product header, making these bars redundant.
   */
  showActionButtons?: boolean;
  /** Called when the user clicks the "Find Your Size" link beside the size selector. */
  onFindYourSizeClick?: () => void;
  /** Called when the user clicks the "Size Guide" inside the size selector. */
  onSizeGuideClick?: () => void;
};

/*
 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
 * pages/product-detail).
 */
type ProductViewRef = React.ForwardedRef<HTMLDivElement>;

/**
 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
 * below. A consumer names it as the `this` parameter of its ref callback —
 * `function (this: ProductViewRefScope, ref) { ... }` — which TypeScript accepts as a `ref`
 * as written; no assertion is required at the prop site.
 */
export type ProductViewRefScope = {
  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
};

const ProductViewHeader = ({
  name,
  currency,
  priceData,
  category,
  product,
  isProductPartOfBundle,
  wishlistButton,
}: ProductViewHeaderProps) => {
  return (
    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
      {category && (
        <Skeleton isLoaded={category} minWidth={64}>
          <Breadcrumb categories={category} />
        </Skeleton>
      )}

      {/* Title row — name on the left, optional wishlist button on the right */}
      <Flex justify="space-between" align="flex-start" width="100%">
        <Skeleton isLoaded={name}>
          <Heading fontSize="2xl">{`${name}`}</Heading>
        </Skeleton>
        {wishlistButton}
      </Flex>

      {!isProductPartOfBundle && (
        <>
          <Skeleton isLoaded={priceData?.currentPrice}>
            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
          </Skeleton>

          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
        </>
      )}
    </VStack>
  );
};

/**
 * Render a product detail view that includes name, image gallery, price,
 * variant selections, action buttons
 */

const ProductView = forwardRef(
  (
    {
      product,
      category,
      showFullLink = false,
      // SFCC-731 review finding (CodeRabbit, 2026-09-02): ZimmProductGallery has no
      // size-variant concept, so this was briefly a no-op — a real regression for the
      // unmodified base callers that pass imageSize="sm" (product-view-modal's quick-view and
      // bundle paths, bonus-product-view-modal), whose compact-modal gallery would otherwise
      // have silently switched to the full PDP gallery. Fixed by branching on it below: 'sm'
      // keeps the base ImageGallery exactly as before, ZimmProductGallery only renders for the
      // PDP's own 'md' (default) path.
      imageSize = 'md',
      isWishlistLoading = false,
      addToCart,
      updateCart,
      addToWishlist,
      removeFromWishlist,
      wishlistedProductIds = [],
      isWishlistMutating = false,
      isProductLoading,
      isProductPartOfSet = false,
      isProductPartOfBundle = false,
      childOfBundleQuantity = 0,
      childProductOrderability,
      setChildProductOrderability,
      isBasketLoading = false,
      onVariantSelected = () => {},
      validateOrderability = (variant, product, quantity, stockLevel) => {
        if (isProductLoading) return false;

        // If product has variations, a variant must be selected
        if (product?.variationAttributes?.length > 0 && !variant) {
          return false;
        }

        // Check if product (either variant or standard) is orderable and if quantity is valid
        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
      },
      showImageGallery = true,
      setSelectedBundleQuantity = () => {},
      selectedBundleParentQuantity = 1,
      pickupInStore = false,
      setPickupInStore = () => {},
      onOpenStoreLocator = () => {},
      showDeliveryOptions = true,
      customButtons = [],
      maxOrderQuantity = null,
      basketProductItems = [],
      imageGalleryFooter = null,
      controlledVariationValues = null,
      onVariationChange = null,
      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
      renderVariationAttribute,
      footerLinks = null,
      showQuantityPicker = true,
      showStockMessage = true,
      showActionButtons = true,
      onFindYourSizeClick,
      onSizeGuideClick,
    }: ProductViewProps,
    ref: ProductViewRef,
  ) => {
    const { currency: activeCurrency } = useCurrency();
    const showToast = useToast();
    const intl = useIntl();
    const buildHref = useSafeHref();
    const location = useLocation();
    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
    const {
      isOpen: isAddToCartModalOpen,
      onOpen: onAddToCartModalOpen,
      onClose: onAddToCartModalClose,
    } = useAddToCartModalContext();

    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');

    const theme = useTheme();
    const { confirmingBasket } = useSFPayments();
    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);

    // Tracks the size the shopper picked in the dropdown. product-detail does not pass
    // controlledVariationValues for standard products — colour uses URL navigation, but
    // size must not change the URL (product-detail computes colour swatch hrefs itself so
    // they remain valid even while useDerivedProduct is in controlled mode).
    const [localSizeValue, setLocalSizeValue] = useState<string | null>(null);
    const urlParams = new URLSearchParams(location.search);
    const effectiveControlledVariationValues =
      controlledVariationValues !== null
        ? controlledVariationValues
        : localSizeValue !== null
        ? {
            ...Object.fromEntries(
              (product?.variationAttributes ?? [])
                .filter((a: SfccVariationAttribute) => urlParams.has(a.id))
                .map((a: SfccVariationAttribute) => [a.id, urlParams.get(a.id) as string]),
            ),
            size: localSizeValue,
          }
        : null;
    const effectiveSizeValue = effectiveControlledVariationValues?.size ?? null;

    const {
      showLoading,
      showInventoryMessage,
      inventoryMessage,
      quantity,
      minOrderQuantity,
      setQuantity,
      variant,
      variationParams,
      variationAttributes,
      stockLevel,
      stepQuantity,
      isOutOfStock,
      unfulfillable,
      isSelectedStoreOutOfStock,
      selectedStore,
    } = useDerivedProduct(
      product,
      isProductPartOfSet,
      isProductPartOfBundle,
      pickupInStore,
      effectiveControlledVariationValues,
      onVariationChange,
    );
    const priceData = useMemo(() => {
      return getPriceData(product, { quantity });
    }, [product, quantity]);
    // SFCC-731 AC 15 — gallery overlay's own "Also available in" swatch row. Combines natural
    // same-master variants with SFCC-708's cross-master related swatches, matching
    // product-detail/index.tsx's own `allValues` pattern exactly — the overlay must offer the
    // same colour set the main PDP sidebar does, not a narrower one (SFCC-708's Jira thread).
    const colourAttr = variationAttributes?.find(
      (attr: SfccVariationAttribute) => attr.id === SFCC_COLOUR_ATTRIBUTE_ID,
    );
    const naturalColourValues =
      colourAttr?.values.map((v: SfccVariationValue) => {
        const image = v.image as unknown as { disBaseLink?: string; link?: string } | undefined;
        return {
          value: v.value ?? '',
          name: v.name,
          imageUrl: image?.disBaseLink || image?.link || '',
          href: v.href,
          orderable: v.orderable ?? true,
        };
      }) ?? [];
    const relatedColourValues = buildRelatedSwatches(
      (product?.c_relatedSwatches ?? []) as RelatedSwatch[],
      // Regional link prefixing fix (same class of bug as productListCardMapper.ts's PLP href):
      // productUrlBuilder alone has no site/locale awareness, so its output is run through
      // useSafeHref() before buildRelatedSwatches appends the colour query param.
      (params) => buildHref(productUrlBuilder(params)),
      SFCC_COLOUR_ATTRIBUTE_ID,
    );
    const colourValues = [...naturalColourValues, ...relatedColourValues];
    const selectedColourValue = colourAttr?.selectedValue?.value;
    const canAddToWishlist = !isProductLoading;
    // SFCC-434, AC5/AC6 — recomputes on every render, so switching size or colour (both flow
    // through `variant`) immediately reflects that variant's own wishlist status with no
    // extra effect/subscription needed. Falls back to `product` (mirroring the variant ||
    // product idiom used elsewhere below) so a simple, non-variant product's wishlist status
    // is still read correctly instead of always resolving to false.
    const wishlistProductId = variant?.productId || product?.productId || product?.id;
    const isInWishlist = wishlistProductId ? wishlistedProductIds.includes(wishlistProductId) : false;
    const isProductASet = product?.type?.set;
    const isProductABundle = product?.type?.bundle;
    const errorContainerRef = useRef<HTMLDivElement | null>(null);
    const sizeSelectorRef = useRef<ZimmSizeSelectorHandle | null>(null);
    const [pickupEnabled, setPickupEnabled] = useState(false);
    // SFCC-731 AC 12-25 — the expanded-state gallery overlay's own open state, owned here rather
    // than threaded in as a prop (the old `onOpenGallery` pass-through was left unwired by every
    // caller — see git history). Self-contained to the `imageSize === 'md'` branch below, which
    // is the only place ZimmProductGallery (and now ZimmGalleryOverlay) renders at all.
    const [isGalleryOverlayOpen, setIsGalleryOverlayOpen] = useState(false);
    const storeName = selectedStore?.name;
    const inventoryId = selectedStore?.inventoryId;
    const hasSizeAttribute = variationAttributes.some((a: SfccVariationAttribute) => a.id === SFCC_SIZE_ATTRIBUTE_ID);
    const hasColourAttribute = variationAttributes.some(
      (a: SfccVariationAttribute) => a.id === SFCC_COLOUR_ATTRIBUTE_ID,
    );
    const isColourMissing = hasColourAttribute && !variationParams[SFCC_COLOUR_ATTRIBUTE_ID];
    const { pdp: showExpressOnPDP } = useExpressCheckoutEnabled();

    const [hasSizeRequiredError, setHasSizeRequiredError] = useState(false);

    const isSelectedSizeOOS = (() => {
      const sizeAttr = product?.variationAttributes?.find((a: SfccProduct) => a.id === SFCC_SIZE_ATTRIBUTE_ID);
      const selectedSize = effectiveSizeValue;
      if (!selectedSize || !sizeAttr) return false;
      return sizeAttr.values?.find((v: SfccProduct) => v.value === selectedSize)?.orderable === false;
    })();

    const isMaxOrderQtyReached = useMemo(() => {
      if (maxOrderQuantity == null) return false;
      const productId = variant?.productId;
      if (!productId) return false;
      const inBag = basketProductItems
        .filter((item) => item.productId === productId)
        .reduce((sum, item) => sum + (item.quantity ?? 0), 0);
      return inBag >= maxOrderQuantity;
    }, [maxOrderQuantity, basketProductItems, variant]);

    const handleAddToBag = async () => {
      // aria-disabled keeps the button clickable for screen-reader announcement, so re-check
      // the hard-blocking states before doing any work.
      if (isSelectedSizeOOS || isMaxOrderQtyReached) return;
      // Only gate on size selection when the product actually has a size attribute.
      // Colour-only and simple products must not be blocked by this check.
      if (hasSizeAttribute && !effectiveSizeValue) {
        setHasSizeRequiredError(true);
        // A4 — move focus back to the size selector trigger so keyboard users know where to act.
        // Timeout of 0 lets React flush the error state update before the focus call.
        setTimeout(() => sizeSelectorRef.current?.focusTrigger(), 0);
        return;
      }
      setHasSizeRequiredError(false);

      // Delegate to the full validation + cart mutation + modal flow.
      const hasValidSelection = validateAndShowError();
      if (!hasValidSelection || !addToCart) return;
      try {
        const itemsAdded = await addToCart([{ product, variant, quantity }]);
        if (itemsAdded) {
          onAddToCartModalOpen({ product, itemsAdded, selectedQuantity: quantity });
        }
      } catch {
        showToast({ title: intl.formatMessage(API_ERROR_MESSAGE), status: 'error' });
      }
    };

    const { disableButton, customInventoryMessage } = useMemo(() => {
      let shouldDisableButton = showInventoryMessage;
      let currentInventoryMsg = '';
      if (!shouldDisableButton && (isProductASet || isProductABundle) && childProductOrderability) {
        // if any of the children are not orderable, it will disable the add to cart button
        const unavailableChildProductKey = Object.keys(childProductOrderability).find((key) => {
          return childProductOrderability[key].showInventoryMessage;
        });
        shouldDisableButton = !!unavailableChildProductKey;
        if (unavailableChildProductKey) {
          const unavailableChildProduct = childProductOrderability[unavailableChildProductKey];
          if (unavailableChildProduct.unfulfillable) {
            currentInventoryMsg = intl.formatMessage(
              {
                defaultMessage: 'Only {stockLevel} left for {productName}!',
                id: 'use_product.message.inventory_remaining_for_product',
              },
              {
                stockLevel: unavailableChildProduct.stockLevel,
                productName: unavailableChildProduct.productName,
              },
            );
          }
          if (unavailableChildProduct.isOutOfStock) {
            currentInventoryMsg = intl.formatMessage(
              {
                defaultMessage: 'Out of stock for {productName}',
                id: 'use_product.message.out_of_stock_for_product',
              },
              { productName: unavailableChildProduct.productName },
            );
          }
        }
      }
      return { disableButton: shouldDisableButton, customInventoryMessage: currentInventoryMsg };
    }, [showInventoryMessage, childProductOrderability]);

    const validateAndShowError = (opts: { scrollErrorIntoView?: boolean } = {}) => {
      const { scrollErrorIntoView = true } = opts;
      // Validate that all attributes are selected before proceeding.
      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
      const showError = !isProductASet && !isProductABundle && !hasValidSelection;
      const scrollToError = showError && scrollErrorIntoView;

      toggleShowOptionsMessage(showError);

      if (scrollToError) {
        // Deviation from the base file: `?.`. The base dereferences `current` unguarded here
        // while guarding it in `prepareBasket` below; the two only differ if the error
        // container has not mounted, where the base throws.
        errorContainerRef.current?.scrollIntoView({
          behavior: 'smooth',
          block: 'center',
        });
      }

      return hasValidSelection;
    };
    const cleanupTemporaryBaskets = useCleanupTemporaryBaskets();

    // prepareBasket is used to prepare the basket for express payments
    // useCallback recreates prepareBasket primarily when product or quantity change, along with variant, stockLevel, and product type flags (isProductASet, isProductABundle)
    const prepareBasket = useCallback(async () => {
      // Validate that all attributes are selected before proceeding
      const hasValidSelection = validateOrderability(variant, product, quantity, stockLevel);
      let errorMessage = '';

      if (!hasValidSelection && !isProductASet && !isProductABundle) {
        toggleShowOptionsMessage(true);
        if (errorContainerRef.current) {
          errorContainerRef.current.scrollIntoView({
            behavior: 'smooth',
            block: 'center',
          });
        }
        errorMessage = intl.formatMessage({
          defaultMessage: 'Please select all product options before proceeding with Express Payments',
          id: 'product_view.prepareBasket',
        });

        const error: Error & { isValidationError?: boolean } = new Error(errorMessage);
        error.isValidationError = true;
        throw error;
      }

      // Clean up temporary baskets before creating a new one
      await cleanupTemporaryBaskets();

      // Create a new temporary basket
      const newBasket = await createBasket({
        parameters: {
          temporary: true,
        },
        body: {},
      });

      const selectedProduct = variant || product;
      // Use variant's productId if variant is selected, otherwise use product's id
      const productIdToUse = selectedProduct?.productId || selectedProduct?.id;

      if (!productIdToUse) {
        errorMessage = intl.formatMessage({
          defaultMessage: 'Unable to determine product ID for basket',
          id: 'product_view.prepareBasket',
        });
        throw new Error(errorMessage);
      }
      // Add the product to the temporary basket
      const basketWithItem = await addItemToBasket({
        // SDK param widening — `newBasket` is the basket just created above.
        parameters: { basketId: newBasket.basketId as string },
        body: [
          {
            productId: productIdToUse,
            quantity: quantity,
          },
        ],
      });

      return basketWithItem;
    }, [variant, product, quantity, stockLevel, isProductASet, isProductABundle]);

    // SFCC-434 — the header wishlist badge's own click handling. Kept separate from
    // renderActionButtons()'s handleWishlistItem: that one only ever adds/updates, while this
    // toggles add vs remove based on the current, reactively-derived isInWishlist.
    // intendedAction lets callers pin the action at the moment of intent (e.g. before opening
    // auth), so a wishlist update during authentication cannot reverse the requested direction.
    const handleWishlistToggle = async (intendedAction?: 'add' | 'remove') => {
      // AC1 — size gate runs before anything else, same state/focus behaviour handleAddToBag
      // already uses. Deliberately does NOT check isSelectedSizeOOS or isMaxOrderQtyReached —
      // AC7 requires OOS sizes to remain wishlistable, and the max-order-quantity cap is a
      // repurchase limit that has no meaning for wishlisting.
      if (hasSizeAttribute && !effectiveSizeValue) {
        setHasSizeRequiredError(true);
        setTimeout(() => sizeSelectorRef.current?.focusTrigger(), 0);
        return;
      }
      setHasSizeRequiredError(false);
      const shouldRemove = intendedAction ? intendedAction === 'remove' : isInWishlist;
      try {
        if (shouldRemove) {
          await removeFromWishlist?.(product, variant);
        } else {
          // Quantity is always 1 here — the SFCC wishlist API ignores whatever value is sent and
          // always adds 1 regardless (see handleAddToWishlist's own NOTE in product-detail/index.tsx).
          await addToWishlist?.(product, variant, 1);
        }
      } catch {
        showToast({ title: intl.formatMessage(API_ERROR_MESSAGE), status: 'error' });
      }
    };

    // Builds the header-slot wishlist badge, gated in the order AC1/AC2 require: size first,
    // then auth. Returns null when the caller has wired neither add nor remove (every existing
    // caller before SFCC-434) or for a bundle child (matches renderActionButtons()'s own
    // "child product of bundles do not have add to wishlist button" rule below).
    //
    // Takes a caller-supplied intentIdSuffix rather than hardcoding one id: for imageSize="sm"
    // callers (quick-view modal, bonus-product-view-modal), the mobile pre-gallery header block
    // and the desktop content-column header block both actually mount simultaneously (CSS-hidden
    // at the opposite breakpoint, not conditionally rendered) — so both renderHeader() call
    // sites below build their own ZimmWishlistAuthDrawer/useWishlistAuthDrawer instance at the
    // same time. A single shared intentId there would let either instance's effect steal a
    // pending social-IDP-redirect intent meant for the other (CodeRabbit finding, SFCC-434
    // review) — the same failure mode useWishlistAuthDrawer's own PENDING_WISHLIST_INTENT_KEY
    // comment already warns about for exactly this "more than one mounted instance" scenario.
    const renderWishlistToggle = (intentIdSuffix: string) => {
      if ((!addToWishlist && !removeFromWishlist) || isProductPartOfBundle) return null;

      // Guards against rendering an enabled toggle when the callback for the CURRENT action
      // (add vs remove, from isInWishlist) isn't actually wired — the outer check above only
      // confirms at least one of the two exists, not the specific one this click would need.
      const isCurrentActionAvailable = isInWishlist ? Boolean(removeFromWishlist) : Boolean(addToWishlist);

      const badge = (
        <ZimmWishlistBadge
          isSelected={isInWishlist}
          // wishlistProductId absent means product/variant data hasn't resolved yet (e.g. a
          // caller that omits isProductLoading) — nothing to send addToWishlist/removeFromWishlist
          // with, so the toggle must stay disabled regardless of canAddToWishlist.
          isDisabled={!wishlistProductId || !canAddToWishlist || !isCurrentActionAvailable}
          isLoading={isWishlistLoading || isWishlistMutating}
          aria-label={intl.formatMessage(isInWishlist ? REMOVE_FROM_WISHLIST_ARIA_LABEL : ADD_TO_WISHLIST_ARIA_LABEL)}
          onClick={() => {
            void handleWishlistToggle();
          }}
        />
      );

      // Only wrap in the auth drawer once a size is selected (or the product has no size
      // attribute at all) — wrapping unconditionally would let ZimmWishlistAuthDrawer's
      // cloneElement run the auth check before the size check ever gets a chance to fire.
      if (hasSizeAttribute && !effectiveSizeValue) {
        return badge;
      }

      // Distinct intentId from the CTA-column button's hardcoded "pdp-wishlist", and distinct
      // per call site via intentIdSuffix — see this function's own doc comment above.
      // Capture the intended action before opening auth — isInWishlist can change during
      // authentication (e.g. another tab updates the wishlist), which would cause
      // handleWishlistToggle() to apply the wrong action on onAuthSuccess.
      const intendedAction = isInWishlist ? 'remove' : 'add';
      return (
        <ZimmWishlistAuthDrawer
          intentId={`pdp-header-wishlist-${intentIdSuffix}`}
          onAuthSuccess={() => {
            void handleWishlistToggle(intendedAction);
          }}
        >
          {badge}
        </ZimmWishlistAuthDrawer>
      );
    };

    const renderActionButtons = () => {
      const buttons = [];
      const buttonText = {
        update: intl.formatMessage({
          defaultMessage: 'Update',
          id: 'product_view.button.update',
        }),
        addToCart: intl.formatMessage({
          defaultMessage: 'Add to Cart',
          id: 'product_view.button.add_to_cart',
        }),
        addSetToCart: intl.formatMessage({
          defaultMessage: 'Add Set to Cart',
          id: 'product_view.button.add_set_to_cart',
        }),
        addBundleToCart: intl.formatMessage({
          defaultMessage: 'Add Bundle to Cart',
          id: 'product_view.button.add_bundle_to_cart',
        }),
        addToWishlist: intl.formatMessage({
          defaultMessage: 'Add to Wishlist',
          id: 'product_view.button.add_to_wishlist',
        }),
        addSetToWishlist: intl.formatMessage({
          defaultMessage: 'Add Set to Wishlist',
          id: 'product_view.button.add_set_to_wishlist',
        }),
        addBundleToWishlist: intl.formatMessage({
          defaultMessage: 'Add Bundle to Wishlist',
          id: 'product_view.button.add_bundle_to_wishlist',
        }),
      };

      const showError = () => {
        showToast({
          title: intl.formatMessage(API_ERROR_MESSAGE),
          status: 'error',
        });
      };

      const handleCartItem = async () => {
        const hasValidSelection = validateAndShowError();

        if (!hasValidSelection) {
          return null;
        }

        if (!addToCart && !updateCart) return null;
        if (updateCart) {
          await updateCart(variant || product, quantity);
          return;
        }
        try {
          // Guarded above: `!addToCart && !updateCart` returns early, and the `updateCart`
          // branch returns, so `addToCart` is defined here. TypeScript cannot narrow across
          // those two statements.
          const itemsAdded = await addToCart!([{ product, variant, quantity }]);
          // Open modal only when `addToCart` returns some data
          // It's possible that the item has been added to cart, but we don't want to open the modal.
          // See wishlist_primary_action for example.
          if (itemsAdded) {
            onAddToCartModalOpen({
              product,
              itemsAdded,
              selectedQuantity: quantity,
            });
          }
        } catch (e) {
          showError();
        }
      };

      // child product of bundles do not have add to cart button
      if ((addToCart || updateCart) && !isProductPartOfBundle) {
        if (updateCart) {
          buttons.push(
            <Button
              key="cart-button"
              onClick={handleCartItem}
              isDisabled={disableButton}
              isLoading={isBasketLoading}
              width="100%"
              variant="solid"
              marginBottom={4}
            >
              {isProductASet
                ? buttonText.addSetToCart
                : isProductABundle
                ? buttonText.addBundleToCart
                : buttonText.update}
            </Button>,
          );
        } else if (!hasSizeAttribute) {
          // Sized products render Add to Bag inline below ZimmSizeSelector; skip it here.
          buttons.push(
            <Box key="cart-button" marginBottom="var(--zimm-scale-m)">
              {isMaxOrderQtyReached && (
                <Text
                  id="max-qty-msg-default"
                  role="alert"
                  textStyle="caption"
                  color="var(--zimm-color-status-error)"
                  textAlign="left"
                  marginBottom="var(--zimm-scale-300)"
                >
                  {intl.formatMessage(MAX_ORDER_QTY_NO_SIZE_MESSAGE)}
                </Text>
              )}
              <ZimmButton
                label={intl.formatMessage(ADD_TO_BAG_MESSAGE)}
                variant="primary"
                fullWidth={true}
                disabled={isBasketLoading || disableButton}
                ariaDisabled={isSelectedSizeOOS || isMaxOrderQtyReached}
                ariaDescribedBy={isMaxOrderQtyReached ? 'max-qty-msg-default' : undefined}
                onClick={() => {
                  void handleAddToBag();
                }}
              />
            </Box>,
          );
        }
      }

      if (showExpressOnPDP && !isProductASet && !isProductPartOfBundle && activeCurrency && priceData.currentPrice) {
        buttons.push(
          <SFPaymentsExpressButtons
            key="express-buttons"
            usage={EXPRESS_BUY_NOW}
            paymentCurrency={activeCurrency}
            paymentCountryCode={null}
            initialAmount={priceData.currentPrice}
            prepareBasket={prepareBasket}
            expressButtonLayout="vertical"
            maximumButtonCount={1}
          />,
        );
      }

      // Add custom buttons if provided
      if (customButtons && customButtons.length > 0) {
        customButtons.forEach((customButton, index) => {
          buttons.push(
            React.cloneElement(customButton, {
              key: `custom-button-${index}`,
              width: customButton.props.width || '100%',
              marginBottom: customButton.props.marginBottom || 4,
            }),
          );
        });
      }

      return buttons;
    };

    // Bind the reference with our `scope` that includes the internal validate function for this component.
    // Other values can be added to this scope as required.
    if (typeof ref === 'function') {
      ref = ref.bind({ validateOrderability: validateAndShowError });
    }

