 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff beyond the TypeScript annotations below, the
 * `useItemVariant` import path rewrite (see next paragraph), and the temporary `[overrides]`
 * console.log marker. The `<Stack spacing={1.5} flex={1} {...props}>` defaults-then-spread prop
 * order is preserved exactly, unchanged from base.
 *
 * The base file imports `useItemVariant` from the SFCC package path
 * (`@salesforce/retail-react-app/app/components/item-variant`) — inconsistent with its own three
 * siblings (item-image/item-name/item-price), which all already import it via the relative `'.'`.
 * Since `item-variant/index.tsx` is itself being overridden in this same commit,
 * this import is rewritten to match its siblings (`'.'`) per
 * .claude/rules/overrideStyling.md's "Importing an already-overridden component from a new
 * component" — a base-path import here would silently exercise the base `useItemVariant`/context
 * in Storybook and Vitest instead of this override.
 *
 * `useCurrentBasket` (from the SFCC hooks path) and the `useCurrency`/`app/hooks` barrel are not
 * overridden anywhere in this repo (verified by directory listing at time of writing — no
 * overrides/app/hooks/use-current-basket.ts, no overrides/app/hooks/index.ts), so both stay on
 * the base `@salesforce/retail-react-app/...` path.
 */
import React from 'react'
import {useIntl, FormattedMessage, FormattedNumber} from 'react-intl'
import {Flex, Stack, Text, Box} from '@salesforce/retail-react-app/app/components/shared/ui'
import {useItemVariant} from '.'
import PromoPopover from '@salesforce/retail-react-app/app/components/promo-popover'
import {useCurrency} from '@salesforce/retail-react-app/app/hooks'
import {useCurrentBasket} from '@salesforce/retail-react-app/app/hooks/use-current-basket'
import {usePromotions, useProducts, useProduct} from '@salesforce/commerce-sdk-react'
import {getDisplayVariationValues} from '@salesforce/retail-react-app/app/utils/product-utils'

// See index.tsx's own note on why this is `any` rather than a structural type.
type SfccVariant = any

type ItemAttributesProps = {
    includeQuantity?: boolean
    currency?: string
    excludeBonusLabel?: boolean
    hideAttributeLabels?: boolean
} & Record<string, any>

/**
 * In the context of a cart product item variant, this component renders a styled
 * list of the selected variation values as well as any promos (w/ info popover).
 */
const ItemAttributes = ({
    includeQuantity,
    currency,
    excludeBonusLabel,
    hideAttributeLabels = false,
    ...props
}: ItemAttributesProps) => {
    console.log('[overrides] item-attributes.tsx')
    const variant: SfccVariant = useItemVariant()
    const {data: basket} = useCurrentBasket()
    const {currency: activeCurrency} = useCurrency()
    const promotionIds = variant.priceAdjustments?.map((adj: SfccVariant) => adj.promotionId) ?? []
    const intl = useIntl()

    const displayBonusProductLabel = !excludeBonusLabel && variant?.bonusProductLineItem

    // Fetch all the promotions given by price adjustments. We display this info in
    // the promotion info popover when applicable.
    const {data: res} = usePromotions(
        {
            parameters: {
                ids: promotionIds.join(',')
            }
        },
        {
            enabled: promotionIds.length > 0
        }
    )
    const promos = res?.data || []
    const variationValues = getDisplayVariationValues(
        variant?.variationAttributes,
        variant?.variationValues
    )

    // get variant info for bundled products in cart page and order history page
    const productBundleIds =
        variant?.bundledProductItems?.map(({productId}: SfccVariant) => productId).join(',') ?? ''
    const {data: productBundleVariantData, isLoading: bundleVariantIsLoading} = useProducts(
        {
            parameters: {
                ids: productBundleIds,
                allImages: false
            }
        },
        {
            enabled: Boolean(variant?.type?.bundle && productBundleIds),
            select: (result: SfccVariant) => {
                // formats response so we can easily display child quantity/variant selection
                return result?.data?.map((item: SfccVariant) => {
                    const quantity = variant?.bundledProductItems.find(
                        (childProduct: SfccVariant) => childProduct.productId === item.id
                    )?.quantity
                    return {
                        ...item,
                        quantity,
                        variationValues: getDisplayVariationValues(
                            item?.variationAttributes,
                            item?.variationValues
                        )
                    }
                })
            }
        }
    )

    // get bundle product data for wishlist page
    const {data: productBundleData, isLoading: productBundleIsLoading} = useProduct(
        {
            parameters: {
                id: variant?.id,
                allImages: false
            }
        },
        {
            enabled: Boolean(variant?.type?.bundle && !productBundleIds)
        }
    )

    return (
        <Stack spacing={1.5} flex={1} {...props}>
            {displayBonusProductLabel && (
                <Text lineHeight={1} color="black.600" fontSize="sm">
                    <FormattedMessage
                        defaultMessage="Bonus Product"
                        id="item_attributes.label.bonus_product"
                    />
                </Text>
            )}

            {variationValues &&
                Object.keys(variationValues).map((key) => (
                    <Text
                        lineHeight={1}
                        color="gray.700"
                        fontSize="sm"
                        key={`${key}: ${variationValues[key]}`}
                    >
                        {hideAttributeLabels
                            ? variationValues[key]
                            : `${key}: ${variationValues[key]}`}
                    </Text>
                ))}

            {includeQuantity && (
                <Text lineHeight={1} color="gray.700" fontSize="sm">
                    <FormattedMessage
                        defaultMessage="Quantity: {quantity}"
                        values={{quantity: variant.quantity}}
                        id="item_attributes.label.quantity"
                    />
                </Text>
            )}

            {!productBundleIsLoading && productBundleData && !productBundleVariantData && (
                <Box>
                    {/* Deviation from the base file (same labelled-comment convention as
                        product-view/index.tsx:659-661/1019-1022): added `?.` before `.map` —
                        `bundledProducts` is itself optional on the SDK's real Product type even
                        once `productBundleData` is truthy, which strict null checks catches and
                        the base file's plain JS did not need to guard against. */}
                    {productBundleData?.bundledProducts?.map(({product, quantity}: SfccVariant) => (
                        <Box marginTop={2} key={product.id}>
                            <Text fontSize="sm" color="gray.700" as="b">
                                {product?.name}
                            </Text>
                            <Text fontSize="sm" color="gray.700">
                                {intl.formatMessage({
                                    defaultMessage: 'Qty',
                                    id: 'add_to_cart_modal.label.quantity'
                                })}
                                : {quantity}
                            </Text>
                        </Box>
                    ))}
                </Box>
            )}

            {!bundleVariantIsLoading && productBundleVariantData && (
                <Box>
                    <Text fontSize={15} marginTop={3} fontWeight={500}>
                        {intl.formatMessage({
                            defaultMessage: 'Selected Options',
                            id: 'item_attributes.label.selected_options'
                        })}
                        :
                    </Text>
                    {productBundleVariantData?.map(
                        ({variationValues, name: productName, quantity, id}: SfccVariant) => {
                            return (
                                <Box key={id} marginTop={2}>
                                    <Text fontSize="sm" color="gray.700" as="b">
                                        {productName}
                                    </Text>
                                    <Text fontSize="sm" color="gray.700">
                                        {intl.formatMessage({
                                            defaultMessage: 'Qty',
                                            id: 'add_to_cart_modal.label.quantity'
                                        })}
                                        : {quantity}
                                    </Text>
                                    {Object.keys(variationValues).map((key) => {
                                        const selectedVariant = `${key}: ${variationValues[key]}`
                                        return (
                                            <Text
                                                fontSize="sm"
                                                color="gray.700"
                                                key={selectedVariant}
                                            >
                                                {selectedVariant}
                                            </Text>
                                        )
                                    })}
                                </Box>
                            )
                        }
                    )}
                </Box>
            )}

            {variant.priceAdjustments?.length > 0 && (
                <Flex alignItems="center">
                    <Text lineHeight={1} color="gray.700" fontSize="sm">
                        <FormattedMessage
                            defaultMessage="Promotions"
                            id="item_attributes.label.promotions"
                        />
                        {': '}
                        <Text as="span" color="green.700">
                            <FormattedNumber
                                style="currency"
                                currency={currency || basket?.currency || activeCurrency}
                                value={variant.priceAdjustments.reduce(
                                    (acc: number, adj: SfccVariant) => acc + (adj.price ?? 0),
                                    0
                                )}
                            />
                        </Text>
                    </Text>
                    <PromoPopover ml={2}>
                        <Stack>
                            {promos?.map((promo: SfccVariant) => (
                                <Text key={promo?.id} fontSize="sm">
                                    {promo?.calloutMsg}
                                </Text>
                            ))}
                        </Stack>
                    </PromoPopover>
                </Flex>
            )}
        </Stack>
    )
}

export default ItemAttributes

